test('when variadic used with choices and two values then set in array', () => {
  const program = new commander.Command();
  program.addOption(
    new commander.Option('-r,--required <value...>').choices([
      'one',
      'two',
    ]),
  );

  program.parse(['--required', 'one', 'two'], { from: 'user' });
  assert.deepEqual(program.opts().required, ['one', 'two']);
});

### 作为属性的遗留选项

在 Commander 7 以前，选项的值是作为属性存储在命令对象上的。
这种处理方式便于实现，但缺点在于，选项可能会与`Command`的已有属性相冲突。通过使用`.storeOptionsAsProperties()`，可以恢复到这种旧的处理方式，并可以不加改动地继续运行遗留代码。

```js
program
  .storeOptionsAsProperties()
  .option('-d, --debug')
  .action((commandAndOptions) => {
    if (commandAndOptions.debug) {
      console.error(`Called ${commandAndOptions.name()}`);
    }
  });
```

test('when variadic used with choices and two values then set in array', () => {
  const program = new commander.Command();
  let passedArg;
  program
    .addArgument(new commander.Argument('<value...>').choices(['one', 'two']))
    .action((value) => {
      passedArg = value;
    });

  program.parse(['one', 'two'], { from: 'user' });
  assert.deepEqual(passedArg, ['one', 'two']);
});

### 变长参数选项

定义选项时，可以通过使用`...`来设置参数为可变长参数。在命令行中，用户可以输入多个参数，解析后会以数组形式存储在对应属性字段中。在输入下一个选项前（`-`或`--`开头），用户输入的指令均会被视作变长参数。与普通参数一样的是，可以通过`--`标记当前命令的结束。

示例代码：[options-variadic.js](./examples/options-variadic.js)

