    dotenv_path = tmp_path / ".env"
    dotenv_path.write_text("")
    dotenv_obj = DotEnv(dotenv_path)

    with mock.patch.object(dotenv_obj, "parse", wraps=dotenv_obj.parse) as mock_parse:
